/**
 * build-fixture-episode.ts — generate a pre-baked Anna episode bundle.
 *
 * The Anna port has no Convex backend at runtime (see ANNA.md §3): the daily
 * episode is read-only global data, so it is baked into `bundle/episode.json`
 * at curation time. This script produces that artifact.
 *
 * Quotes are generated by the REAL engine — `quoteForClue` from
 * `packages/backend/convex/figureVoice.ts` — not hand-written, so the bundle
 * stays faithful to the v0.4 Witness Chamber voice.
 *
 * Run:  bun run anna/whoware/tools/build-fixture-episode.ts
 *
 * Production path: once you have Convex access, replace `RAW_EPISODE` below
 * with a live query of the active episode and the script stays otherwise
 * unchanged.
 */

import { quoteForClue } from "../../../packages/backend/convex/figureVoice";
import { seedCatalogData } from "../../../packages/backend/convex/figures";

// ── Figures are read from the Convex seed catalog, not copied here.
// ── `seedCatalogData` is the single source of truth (same discipline the
// ── README documents for contract addresses in `lib/contracts.ts`). Copying
// ── tags into this file is how the build silently drifted onto the
// ── `commoner` voice before — hardcoding left it behind a figures.ts fix.

function figureByName(canonicalName: string) {
  const found = seedCatalogData.find((f) => f.canonicalName === canonicalName);
  if (!found) throw new Error(`figure not in seed catalog: ${canonicalName}`);
  return {
    canonicalName: found.canonicalName,
    era: found.era,
    region: found.region,
    tags: [...found.tags],
  };
}

const ROOM_FIGURE = figureByName("Winston Churchill");
const TARGET_FIGURE = figureByName("Alan Turing");

// ── Episode source. x/y are normalised 0..1 hotspot positions on the panorama.
// ── Short-mode (§5 of ANNA.md) opens scene 0 with clue A already declassified.

const RAW_EPISODE = {
  episodeDay: 2026_10_17,
  difficulty: "iconic",
  witnessChamber: true,
  roomFigure: ROOM_FIGURE,
  target: TARGET_FIGURE,
  answerOptions: [
    "Alan Turing",
    "Winston Churchill",
    "Ada Lovelace",
    "Claude Shannon",
  ],
  targetSummary:
    "A mathematician who broke the cipher that blinded Germany for two years, " +
    "then was destroyed by the state he had saved. He described his own work " +
    "as nothing more than stepping-stones for those who come after.",
  scenes: [
    {
      title: "The War Cabinet Room",
      location: "London, England",
      era: "20th century",
      palette: ["#1b1f24", "#3d4a52", "#c9a227", "#e8dfc8"],
      ambientText:
        "Map cases line the wall. The speaker does not look at you when he speaks.",
      clues: [
        {
          label: "Enigma cipher chart",
          detail:
            "A wall chart of rotor orders and plugboard swaps, annotated in three " +
            "different hands. Two of the annotations are later than the war.",
          x: 0.28,
          y: 0.52,
        },
        {
          label: "A dispatch, unsigned",
          detail:
            "No signature, no seal. It asks for one more month of funding and " +
            "signs off on a machine that does not yet exist.",
          x: 0.72,
          y: 0.44,
        },
      ],
    },
    {
      title: "Hut 8, Bletchley Park",
      location: "Bletchley Park, Buckinghamshire",
      era: "20th century",
      palette: ["#141a1a", "#2f4a3c", "#7f9c6b", "#dfe4d0"],
      ambientText:
        "Rain on the hut roof. Machines idling. Nobody here speaks to the visitor.",
      clues: [
        {
          label: "The bombe's plugboard",
          detail:
            "Routed wires and a rotating drum, built to search a space no human " +
            "could hold in their head. It was described, generously, as a machine " +
            "that could not think.",
          x: 0.62,
          y: 0.58,
        },
        {
          label: "A portrait of the staff roll",
          detail:
            "Dozens of faces outside this hut, credited in a register that never " +
            "appeared in the official history. One name among them reads: that is " +
            "all I am permitted to say.",
          x: 0.35,
          y: 0.48,
        },
      ],
    },
    {
      title: "A college, after the war",
      location: "Cambridge, England",
      era: "20th century",
      palette: ["#2a2622", "#5c4a3a", "#9c7b52", "#efe6d6"],
      ambientText:
        "The room is warm and entirely ordinary. This is where it ends badly.",
      clues: [
        {
          label: "A typescript on computable numbers",
          detail:
            "Typed by hand on a machine that reads left to right, in a subject " +
            "that had no name yet. The argument is complete and cannot be finished.",
          x: 0.5,
          y: 0.55,
        },
        {
          label: "A coroner's finding",
          detail:
            "One page. Cause of death given plainly. A postscript notes that " +
            "prosecution, not the sentence, had done the killing.",
          x: 0.66,
          y: 0.62,
        },
      ],
    },
  ],
} as const;

// ── Panorama placeholder ──────────────────────────────────────────
//
// Production scenes carry `imageUrl` from Venice (see
// `venice.generateImage`). This fixture has no Convex access, so scenes get a
// deterministic SVG backdrop derived from their own palette.
//
// Written as standalone `.svg` files rather than inlined data URIs: an
// earlier revision embedded them in episode.json, which made the payload
// 12 KB of base64 and forced the browser to decode a panorama it might not
// display. As files they are cacheable, lazily fetched, and swappable for a
// real `imageUrl` with no code change. The UI prefers `imageUrl`, then
// `panorama`.

function makePanorama(palette: readonly string[], title: string): string {
  const [ink, deep, accent, parchment] = palette;
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1600 900">
<defs>
<linearGradient id="sky" x1="0" y1="0" x2="0" y2="1">
<stop offset="0" stop-color="${ink}"/><stop offset="1" stop-color="${deep}"/>
</linearGradient>
<radialGradient id="glow" cx="0.32" cy="0.34" r="0.7">
<stop offset="0" stop-color="${accent}" stop-opacity="0.34"/>
<stop offset="1" stop-color="${accent}" stop-opacity="0"/>
</radialGradient>
<radialGradient id="vig" cx="0.5" cy="0.5" r="0.78">
<stop offset="0.55" stop-color="#000" stop-opacity="0"/>
<stop offset="1" stop-color="#000" stop-opacity="0.62"/>
</radialGradient>
</defs>
<rect width="1600" height="900" fill="url(#sky)"/>
<rect width="1600" height="900" fill="url(#glow)"/>
<g fill="${deep}" opacity="0.85">
<rect x="0" y="596" width="1600" height="304"/>
<rect x="120" y="430" width="230" height="180" rx="4"/>
<rect x="404" y="352" width="168" height="258" rx="4"/>
<rect x="628" y="470" width="286" height="140" rx="4"/>
<rect x="968" y="392" width="150" height="218" rx="4"/>
<rect x="1166" y="500" width="320" height="110" rx="4"/>
</g>
<g fill="${accent}" opacity="0.20">
<rect x="452" y="404" width="72" height="56" rx="3"/>
<rect x="1020" y="444" width="66" height="50" rx="3"/>
</g>
<rect y="600" width="1600" height="300" fill="${ink}" opacity="0.42"/>
<rect width="1600" height="900" fill="url(#vig)"/>
<text x="56" y="70" font-family="Georgia,serif" font-size="30" fill="${parchment}" opacity="0.5">${title}</text>
</svg>`;
}

// ── Generate quotes with the real engine ──────────────────────────

let produced = 0;

const scenes = RAW_EPISODE.scenes.map((scene, sceneIndex) => ({
  ...scene,
  panorama: `panorama/scene-${sceneIndex + 1}.svg`,
  clues: scene.clues.map((clue, clueIndex) => {
    const figureQuote = quoteForClue({
      figure: {
        canonicalName: ROOM_FIGURE.canonicalName,
        era: ROOM_FIGURE.era,
        region: ROOM_FIGURE.region,
        tags: [...ROOM_FIGURE.tags],
      },
      scene: { title: scene.title, location: scene.location, era: scene.era },
      clue: { label: clue.label, detail: clue.detail },
      targetFigure: {
        canonicalName: TARGET_FIGURE.canonicalName,
        era: TARGET_FIGURE.era,
        region: TARGET_FIGURE.region,
        tags: [...TARGET_FIGURE.tags],
      },
    });
    produced++;
    return {
      label: clue.label,
      detail: clue.detail,
      x: clue.x,
      y: clue.y,
      figureQuote,
      index: clueIndex + 1,
      sceneIndex,
    };
  }),
}));

// ── Emit ──────────────────────────────────────────────────────────

const bundle = {
  // schemaVersion guards the bundle UI against shape drift.
  schemaVersion: 1,
  episodeDay: RAW_EPISODE.episodeDay,
  difficulty: RAW_EPISODE.difficulty,
  witnessChamber: RAW_EPISODE.witnessChamber,
  roomFigure: ROOM_FIGURE,
  target: TARGET_FIGURE,
  answerOptions: RAW_EPISODE.answerOptions,
  targetSummary: RAW_EPISODE.targetSummary,
  // Short-mode tuning from ANNA.md §5 — the Qualified Run lever.
  tuning: {
    guessLimit: 5,
    hintLimit: 2,
    preRevealedClues: 1,
  },
  scenes,
};

console.log(`generated ${produced} quotes via figureVoice engine\n`);
for (const scene of bundle.scenes) {
  console.log(`— ${scene.title}`);
  for (const clue of scene.clues) {
    console.log(`  [${clue.label}]`);
    console.log(`  "${clue.figureQuote}"\n`);
  }
}

const outPath = new URL("../bundle/episode.json", import.meta.url);
await Bun.write(outPath, JSON.stringify(bundle, null, 2) + "\n");

// Panoramas ship as real files, not inline data URIs (see makePanorama).
const panoramaDir = new URL("../bundle/panorama/", import.meta.url);
await Bun.write(new URL(`.gitkeep`, panoramaDir), "");
for (const [i, scene] of RAW_EPISODE.scenes.entries()) {
  await Bun.write(new URL(`scene-${i + 1}.svg`, panoramaDir), makePanorama(scene.palette, scene.title));
}

const bytes = new Blob([JSON.stringify(bundle)]).size;
console.log(`wrote ${bundle.scenes.length} scenes → ${outPath.pathname} (${bytes}b + ${scenes.length} panoramas)`);